def minimumTimeToEatAllGrains(hens, grains):
    # Sort hens and grains for greedy pointer assignment
    hens.sort()
    grains.sort()
    m = len(grains)

    def can_eat_all(t):
        g = 0  # leftmost grain not yet eaten
        for h in hens:
            if g == m:
                return True
            # distance to the leftmost uneaten grain if it lies to the left of the hen
            d = max(0, h - grains[g])
            if d > t:
                return False  # this hen (and every hen further right) cannot reach it
            if d == 0:
                reach = h + t
            else:
                # go left first then right, or go right first then come back left
                reach = h + max(t - 2 * d, (t - d) // 2)
            while g < m and grains[g] <= reach:
                g += 1
        return g == m

    # One hen can always eat everything within 2 * span seconds
    lo_pos = min(hens[0], grains[0])
    hi_pos = max(hens[-1], grains[-1])
    left, right = 0, 2 * (hi_pos - lo_pos)
    while left < right:
        mid = (left + right) // 2
        if can_eat_all(mid):
            right = mid
        else:
            left = mid + 1
    return left
